/* Navigation and chart-control placement only; delegates chart operations to existing APIs. */
(()=>{'use strict';const $=id=>document.getElementById(id);let root;const SHORTCUT_KEY='kp-master-small-shortcuts-visible-v1';
const route=id=>document.querySelector('.app-sidebar nav [data-tab="'+id+'"]')?.click();
function fresh(kind){route('basic');const prefix='pc-'+kind+'-';window.KPComputerForms?.fromChart(kind);window.KPComputerForms?.setMode(kind);for(const id of ['name','horary-question','chart-notes'])if($(prefix+id))$(prefix+id).value='';const now=new Date(Date.now()+Number($('birth-utc-offset').value)*3600000).toISOString();for(const [id,v]of [['dob',now.slice(0,10)],['birthTime',now.slice(11,19)]])if($(prefix+id))$(prefix+id).value=v;const form=$(prefix+'name')?.closest('.pc-entry-pane')||$(prefix+'name')?.parentElement;form?.scrollIntoView({block:'center'});$(prefix+'name')?.focus();}
const actions={help:()=>$('help-open')?.click(),ruling:()=>KPRulingFinder.open(),open:()=>document.querySelector('.global-actions [data-action="open-kundali"]')?.click(),natal:()=>fresh('natal'),horary:()=>fresh('horary'),instant:()=>{KPDefaultLocation.instant();route('south9');},rules:()=>KPRules.open(),notepad:()=>KPNotepad.open(),windows:()=>KPChartWindows.open(),exit:()=>{window.close();if(!window.closed)window.showToast?.('Use the browser tab’s close button to exit.');}};
const groups=[['Home',[['Home','home'],['Open Kundali','@open'],['Edit · Birth details','basic'],['New Horoscope','@natal'],['New Horary','@horary'],['Instant Prashna Chart','@instant'],['Exit','@exit']]],['View',[['Transits','transit'],['Transit Chart','transit-chart'],['Transit Panchang','transit-panchang'],['Muhurta','muhurta'],['DBA/MAP','mdcalc'],['Significators','karyesh']]],['Prediction',[['Prediction','prediction'],['Education & Profession','education-profession'],['Disease','disease'],['Dasha Promise','dasha-promise'],['Event Promise','event-promise']]],['Tools',[['Horary Results','horary-results'],['Ruling Planet','@ruling'],['Ephemeris','ephemeris'],['HIT Theory','hit-theory'],['Vedic Kundali','vedic-kundali'],['Matchmaking','matchmaking'],['Nadi Astrology','nadi-astrology']]],['Basic Information','basic-information'],['Western aspects','aspects'],['Reference',[['KP Resources','resources'],['Tutorial','tutorial'],['Notepad','@notepad'],['Administrator calculations','admin-calculations'],['Rules','@rules']]],['Print report','report'],['South Indian kundali','south9'],['Windows',[['Manage open Kundalis','@windows']]],['Astrologer settings','astrosettings'],['About','about']];
function activate(value){if(value.startsWith('@'))actions[value.slice(1)]?.();else route(value);root.querySelectorAll('details[open]').forEach(n=>n.open=false);}
function button(text,value){const b=document.createElement('button');b.type='button';b.textContent=text;b.dataset.kpMenuAction=value;b.onclick=()=>activate(value);return b;}
function controls(){const source=document.querySelector('#south9 .kundali-toolbar'),anchor=$('kundali-north')||$('kundali');if(source&&anchor){source.classList.add('kp-chart-below-controls');anchor.after(source);const asc=$('kp-asc-moon-tool');if(asc)source.append(asc);const extra=document.querySelector('#south9 .south-action-row');if(extra)source.after(extra);}const home=$('home-kundali');if(home){let bar=$('kp-home-chart-controls');if(!bar){bar=document.createElement('div');bar.id='kp-home-chart-controls';bar.className='kp-chart-below-controls no-print';home.after(bar);for(const [label,fn]of [['Update Chart',()=>document.querySelector('#south9 .kundali-toolbar button[data-cusp-tool]')?.previousElementSibling?.click()],['Cusp Setting Tool',()=>KPManualCusps.open()],['Save',()=>document.querySelector('.global-actions [data-action="save-kundali"]')?.click()],['Ascendant / Moon transitions',()=>KPChartWorkspace.transitions()]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=fn;bar.append(b);}}const fonts=document.querySelector('#home [data-lord-control="home"]');if(fonts&&fonts.parentElement!==bar)bar.prepend(fonts);}document.querySelectorAll('.kp-chart-readable').forEach(n=>n.remove());}
function shortcutState(){const p=window.KPPreferences?.get()||{},keys=['Home','Natal','Horary','Instant','Open','Transit','RP','Ephemeris','Settings','Notepad','Help'];root?.querySelectorAll('.kp-small-shortcuts>button').forEach((b,i)=>{b.dataset.shortcutKey=keys[i];b.hidden=p['shortcut'+keys[i]]===false;});}
function sidebarState(){shortcutState();const hidden=!!window.KPPreferences?.get().sidebarHidden;document.body.classList.toggle('kp-sidebar-hidden',hidden);const button=$('kp-left-panel-toggle');if(button){button.setAttribute('aria-expanded',String(!hidden));button.title=hidden?'Show left panel':'Hide left panel';}}
function popupPosition(){const header=document.querySelector('.workspace-topbar');if(header)document.documentElement.style.setProperty('--kp-rp-top',(Math.max(0,header.getBoundingClientRect().bottom,root?.getBoundingClientRect().bottom||0)+8)+'px');}
function init(){const old=$('kp-quick-tools');if(!old||$('kp-compact-navigation'))return;root=document.createElement('nav');root.id='kp-compact-navigation';root.className='no-print';root.setAttribute('aria-label','KP Master main menu');const menu=document.createElement('div');menu.className='kp-main-menu';for(const [name,target]of groups){if(typeof target==='string')menu.append(button(name,target));else{const details=document.createElement('details'),summary=document.createElement('summary'),list=document.createElement('div');summary.textContent=name;list.className='kp-menu-options';list.setAttribute('aria-label',name+' options');for(const [label,value]of target)list.append(button(label,value));details.append(summary,list);details.addEventListener('toggle',()=>{if(details.open)menu.querySelectorAll('details').forEach(n=>{if(n!==details)n.open=false;});});menu.append(details);}}const tools=document.createElement('div');tools.className='kp-small-shortcuts';for(const [label,title,target]of [['⌂','Home','home'],['N','New Horoscope','@natal'],['H','New Horary','@horary'],['IP','Instant Prashna Chart','@instant'],['📂','Open Kundali','@open'],['TC','Transit Chart','transit-chart'],['RP','Ruling Planet','@ruling'],['EPh','Ephemeris','ephemeris'],['⚙','Astrologer settings','astrosettings'],['✎','Notepad','@notepad'],['?','Help & shortcuts','@help']]){const b=button(label,target);b.title=title;b.setAttribute('aria-label',title);tools.append(b);}const row=document.createElement('div');row.className='kp-shortcut-row';row.append(tools);const menuHeader=document.createElement('div');menuHeader.className='kp-menu-header';const sidebar=document.createElement('button');sidebar.id='kp-left-panel-toggle';sidebar.type='button';sidebar.textContent='☰';sidebar.setAttribute('aria-label','Show or hide left panel');sidebar.setAttribute('aria-controls','app-sidebar');sidebar.onclick=()=>{KPPreferences.save({...KPPreferences.get(),sidebarHidden:!KPPreferences.get().sidebarHidden});sidebarState();};menuHeader.append(sidebar,menu);root.append(menuHeader,row);old.before(root);old.hidden=true;old.classList.add('kp-legacy-shortcuts');document.body.classList.add('kp-compact-navigation','kp-navigation-ready');sidebarState();window.addEventListener('kp-preferences-changed',sidebarState);window.addEventListener('resize',popupPosition);$('kp-live-ruling')?.addEventListener('toggle',popupPosition);popupPosition();controls();setTimeout(controls,250);document.addEventListener('click',e=>{if(!root.contains(e.target))root.querySelectorAll('details').forEach(n=>n.open=false);});root.addEventListener('keydown',e=>{if(e.key==='Escape'){root.querySelectorAll('details').forEach(n=>n.open=false);e.target.closest('details')?.querySelector('summary')?.focus();}});}
window.KPCompactNavigation=Object.freeze({groups:()=>structuredClone(groups),activate,controls});function start(){if($('kp-quick-tools')){init();return;}const observer=new MutationObserver(()=>{if($('kp-quick-tools')){observer.disconnect();init();}});observer.observe(document.documentElement,{childList:true,subtree:true});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();})();
